import { createSvg } from '../createSvg';
export function renderNewsfeed() {
    // The paths in the newsfeed icon are set in css
    // the points in the d attribute can be animated if the lengths of points are the same between the start and end states
    // thankfully for us they are because this would be a pain to animate otherwise
    return createSvg('svg', {
        width: '24',
        height: '24',
        viewBox: '0 0 24 24'
    }, [
        createSvg('path', {
            class: 'neon-app-nav-icon-newsfeed-1'
        }),
        createSvg('path', {
            class: 'neon-app-nav-icon-newsfeed-2'
        }),
        createSvg('path', {
            class: 'neon-app-nav-icon-newsfeed-3'
        }),
        createSvg('path', {
            class: 'neon-app-nav-icon-newsfeed-4'
        }),
        createSvg('path', {
            class: 'neon-app-nav-icon-newsfeed-5'
        }),
        createSvg('path', {
            opacity: '0.18',
            class: 'neon-app-nav-icon-newsfeed-6'
        }),
    ]);
}
